      <label for="email">Email address</label>
      <input type="email" id="email" name="email" placeholder="jane@example.com" autocomplete="email" required>
    </div>
    <button type="submit" id="submitBtn">
      <span>🎫</span> Claim my seat
    </button>
    <div id="errorMessage" class="error-message">
      <span>⚠️</span> <span id="errorText"></span>
    </div>
  </form>

  <div class="attendee-list">
    <div class="attendee-header">
      <span>Who's coming</span>
      <span id="attendeeCount">0 attendees</span>
    </div>
    <div id="attendeesContainer" class="attendees-container">
      <!-- attendee items injected here -->
      <div class="empty-message">No seats claimed yet. Be the first!</div>
    </div>
    <div id="capacityWarning" class="capacity-warning hidden">
      <span>🔴</span> <span id="capacityWarningText">All seats are taken. No more sign-ups.</span>
    </div>
  </div>
</div>

<script>
  (function() {
    // ---------- CONSTANTS & STATE ----------
    const TOTAL_SEATS = 20;
    // Attendees array: each { name, email }
    let attendees = [];

    // DOM elements
    const form = document.getElementById('signupForm');
    const nameInput = document.getElementById('name');
    const emailInput = document.getElementById('email');
    const submitBtn = document.getElementById('submitBtn');
    const errorMessageDiv = document.getElementById('errorMessage');
    const errorTextSpan = document.getElementById('errorText');
    const seatsLeftDisplay = document.getElementById('seatsLeftDisplay');
    const progressFraction = document.getElementById('progressFraction');
    const progressFill = document.getElementById('progressFill');
    const attendeesContainer = document.getElementById('attendeesContainer');
    const attendeeCountSpan = document.getElementById('attendeeCount');
    const capacityWarning = document.getElementById('capacityWarning');
    const capacityWarningText = document.getElementById('capacityWarningText');

    // ---------- HELPER FUNCTIONS ----------
    function updateUI() {
      const takenSeats = attendees.length;
      const seatsLeft = TOTAL_SEATS - takenSeats;
      const isFull = takenSeats >= TOTAL_SEATS;

      // Update seat badge & progress
      seatsLeftDisplay.textContent = seatsLeft;
      progressFraction.textContent = `${takenSeats} / ${TOTAL_SEATS}`;
      const fillPercent = (takenSeats / TOTAL_SEATS) * 100;
      progressFill.style.width = `${fillPercent}%`;

      // Attendee count
      attendeeCountSpan.textContent = `${takenSeats} attendee${takenSeats !== 1 ? 's' : ''}`;

      // Disable form and show warning if full
      if (isFull) {
        nameInput.disabled = true;
        emailInput.disabled = true;
        submitBtn.disabled = true;
        capacityWarning.classList.remove('hidden');
        capacityWarning.classList.add('full-capacity');
        capacityWarningText.textContent = 'All 20 seats are taken. No more sign-ups.';
      } else {
        nameInput.disabled = false;
        emailInput.disabled = false;
        submitBtn.disabled = false;
        capacityWarning.classList.add('hidden');
        capacityWarning.classList.remove('full-capacity');
      }

      // Render attendees list
      renderAttendees();
    }

    function renderAttendees() {
      // Clear container
      attendeesContainer.innerHTML = '';

      if (attendees.length === 0) {
        // show empty message
        const emptyDiv = document.createElement('div');
        emptyDiv.className = 'empty-message';
        emptyDiv.textContent = 'No seats claimed yet. Be the first!';
        attendeesContainer.appendChild(emptyDiv);
        return;
      }

      // Loop through attendees and append items
      attendees.forEach((person, index) => {
        const seatNumber = index + 1; // seat numbers 1..20
        const item = document.createElement('div');
        item.className = 'attendee-item';

        // seat number badge
        const seatSpan = document.createElement('span');
        seatSpan.className = 'seat-number';
        seatSpan.textContent = `#${seatNumber}`;

        // name
        const nameSpan = document.createElement('span');
        nameSpan.className = 'name';
        nameSpan.textContent = person.name;

        // email
        const emailSpan = document.createElement('span');
        emailSpan.className = 'email';
        emailSpan.textContent = person.email;
        emailSpan.title = person.email;

        item.appendChild(seatSpan);
        item.appendChild(nameSpan);
        item.appendChild(emailSpan);
        attendeesContainer.appendChild(item);
      });
    }

    function showError(message) {
      errorTextSpan.textContent = message;
      errorMessageDiv.classList.add('show');
      // auto hide after 4 seconds? optional; we keep visible until next action. But we'll clear on input.
    }

    function clearError() {
      errorMessageDiv.classList.remove('show');
      errorTextSpan.textContent = '';
    }

    // validation for uniqueness of email (case-insensitive)
    function isEmailTaken(email) {
      const lowerEmail = email.trim().toLowerCase();
      return attendees.some(person => person.email.toLowerCase() === lowerEmail);
    }

    // ---------- EVENT HANDLERS ----------
    function handleSubmit(event) {
      event.preventDefault();

      // Clear previous error
      clearError();

      // Read values
      const name = nameInput.value.trim();
      const email = emailInput.value.trim();

      // Basic field validation
      if (!name || !email) {
        showError('Please fill in both name and email.');
        return;
      }

      if (!email.includes('@') || !email.includes('.')) {
        showError('Please enter a valid email address.');
        return;
      }

      // Check if we already have 20 attendees
      if (attendees.length >= TOTAL_SEATS) {
        showError('Sorry, all 20 seats are already taken.');
        updateUI(); // also disable UI if not already
        return;
      }

      // Check for duplicate email
      if (isEmailTaken(email)) {
        showError('This email address has already been used to claim a seat.');
        return;
      }

      // Optionally: prevent duplicate name? Not necessary, but fine.

      // --- All good: add attendee ---
      attendees.push({ name, email });

      // Clear inputs
      nameInput.value = '';
      emailInput.value = '';

      // Clear any error
      clearError();

      // Update the UI (seat counts, progress, list, disable if full)
      updateUI();

      // Focus back on name for quick entry if seats remain
      if (attendees.length < TOTAL_SEATS) {
        nameInput.focus();
      } else {
        // if full, maybe blur
        nameInput.blur();
        emailInput.blur();
      }
    }

    // Clear error when user starts typing again
    nameInput.addEventListener('input', clearError);
    emailInput.addEventListener('input', clearError);

    // Initialize UI on page load
    function init() {
      // Start with empty attendees
      attendees = [];
      updateUI();
      // set initial empty message, progress etc.
      nameInput.focus();

      // Add form submit listener
      form.addEventListener('submit', handleSubmit);

      // Optional: prevent double-click etc. fine.
    }

    // run init
    init();

    // Expose for testing (optional)
    window.attendees = attendees;  // not necessary but harmless
  })();
</script>
</body>
</html>
```
### Sign-up Form & Seat Management
The page is designed to make claiming a seat simple and transparent. Here's how it works:
*   **Seat Availability:** A badge and a progress bar clearly show how many of the 20 seats are still available, updating in real-time.
*   **Sign-up Process:** Users fill in their name and email. The form validates that both fields are filled and that the email is valid and not already used.
*   **Live Attendee List:** As people sign up, their names and seat numbers appear in a list below the form, giving a sense of community.
*   **Capacity Handling:** Once all 20 seats are claimed, the form is disabled, and a warning message is displayed to prevent further sign-ups.

